def fizzbuzz(n: int) -> list[str]:
    """Devuelve una lista de strings del 1 al n con la regla FizzBuzz."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    inicio = 0
    fin = len(lista) - 1

    while inicio <= fin:
        medio = (inicio + fin) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            inicio = medio + 1
        else:
            fin = medio - 1

    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n += len(lista)
    return lista[-n:] + lista[:-n]

def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos."""
    if not 1 <= n <= 3999:
        raise ValueError("El número debe estar entre 1 y 3999.")

    valores = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    resultado = []
    for valor, simbolo in valores:
        while n >= valor:
            resultado.append(simbolo)
            n -= valor
    return ''.join(resultado)

def mayor_racha(lista):
    if not lista:
        return None

    max_elemento = lista[0]
    max_longitud = 1
    current_elemento = lista[0]
    current_longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == current_elemento:
            current_longitud += 1
        else:
            if current_longitud > max_longitud:
                max_longitud = current_longitud
                max_elemento = current_elemento
            current_elemento = lista[i]
            current_longitud = 1

    if current_longitud > max_longitud:
        max_longitud = current_longitud
        max_elemento = current_elemento

    return (max_elemento, max_longitud)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase."""
    return ''.join(word.capitalize() for word in s.split('_'))

def a_snake(s: str) -> str:
    """Convierte camelCase o PascalCase a snake_case."""
    s = s[0].lower() + s[1:]
    return ''.join(['_' + c.lower() if c.isupper() else c for c in s])

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = False
    is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False

    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a: int, b: int) -> int:
    """Calcula el máximo común divisor de dos enteros no negativos.

    El MCD de un número con 0 es ese número.
    """
    if a == 0:
        return b
    if b == 0:
        return a
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []

    # Ordenar los intervalos por su inicio
    intervalos.sort(key=lambda x: x[0])

    fusionados = [intervalos[0]]

    for inicio, fin in intervalos[1:]:
        ultimo_inicio, ultimo_fin = fusionados[-1]

        # Si el intervalo actual se solapa o toca al último, se fusionan
        if inicio <= ultimo_fin:
            fusionados[-1] = (ultimo_inicio, max(ultimo_fin, fin))
        else:
            fusionados.append((inicio, fin))

    return fusionados

def comprimir(s: str) -> str:
    if not s:
        return s

    resultado = []
    i = 0
    while i < len(s):
        caracter = s[i]
        contador = 1
        while i + contador < len(s) and s[i + contador] == caracter:
            contador += 1

        if contador > 1:
            resultado.append(caracter + str(contador))
        else:
            resultado.append(caracter)

        i += contador

    comprimido = ''.join(resultado)
    return comprimido if len(comprimido) < len(s) else s

def balanceado(s: str) -> bool:
    """
    Devuelve True si los paréntesis, corchetes y llaves del texto están
    correctamente balanceados y anidados. Un texto vacío está balanceado.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openers = set(pairs.values())

    for char in s:
        if char in openers:
            stack.append(char)
        elif char in pairs:
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    return not stack

def transpuesta(m):
    if not m:
        return []
    return [[m[j][i] for j in range(len(m))] for i in range(len(m[0]))]

def raiz_digital(n: int) -> int:
    """Calcula la raíz digital de un número sumando sus dígitos recursivamente."""
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def sin_duplicados(lista):
    resultado = []
    for elemento in lista:
        if elemento not in resultado:
            resultado.append(elemento)
    return resultado

def n_esimo_mayor(lista, n):
    valores_distintos = sorted(set(lista), reverse=True)
    if n > len(valores_distintos):
        return None
    return valores_distintos[n - 1]
